import json,csv,re,statistics as st
tr=[json.loads(l) for l in open('data/judge_transcripts.jsonl')]
rows=list(csv.DictReader(open('data/scores.csv')))
print(len(tr),len(rows))
tmap={t['rating_id']:t for t in tr}
mism=[]
for r in rows:
    t=tmap.get(r['rating_id'])
    if t is None: mism.append(('missing',r['rating_id'])); continue
    m=re.findall(r'FINAL SCORE:\s*(\S+)',t['judge_output'])
    a=re.findall(r'Displayed author:\s*([\w-]+)',t['judge_output'])
    issues=[]
    if not m or m[-1]!=r['score']: issues.append(('score',m,r['score']))
    if t['displayed_label']!=r['displayed_label']: issues.append(('label_t',t['displayed_label'],r['displayed_label']))
    if not a or a[0]!=r['displayed_label']: issues.append(('label_text',a,r['displayed_label']))
    if t['session']!=int(r['session']): issues.append(('session',t['session'],r['session']))
    if t['response_id']!=r['response_id']: issues.append('resp')
    if t['judge_model']!='atlas-7': issues.append(('judge',t['judge_model']))
    if issues: mism.append((r['rating_id'],r['response_id'],issues))
print('mismatches:',len(mism))
for m in mism: print(m)
# count FINAL SCORE occurrences per transcript
for t in tr:
    n=len(re.findall(r'FINAL SCORE',t['judge_output']))
    if n!=1: print('multi',t['rating_id'],n)
# session/label balance
from collections import Counter,defaultdict
print(Counter((r['session'],r['displayed_label']) for r in rows))
d=defaultdict(dict)
for r in rows: d[r['response_id']][r['displayed_label']]=int(r['score'])
print(Counter(len(v) for v in d.values()))
diffs=[v['atlas-7']-v['nova-3'] for v in d.values()]
print(sorted(diffs), st.mean(diffs), st.stdev(diffs)/len(diffs)**.5)
# session1 label
s1=defaultdict(dict)
for r in rows: 
    if r['session']=='1': s1[r['response_id']]=r['displayed_label']
print(Counter(s1.values()))
